// ============================================================================
// Monitor Vagas Tech - logica pura dos nos "Code" do n8n (fonte unica).
// Este arquivo e: (1) testado por logic-tests.cjs e (2) EMBUTIDO verbatim no
// workflow.json pelo build-workflow.cjs (cada no Code chama estas funcoes).
// Nao usa require() de modulo externo -> roda igual no n8n (sandbox) e no node.
// O guard de module.exports no fim e inerte dentro do n8n (module e undefined).
// ============================================================================

// Hash estavel (djb2) sem depender de crypto/require -> portavel no sandbox n8n.
function hashId(str) {
  let h = 5381;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) + h) + str.charCodeAt(i);
    h = h & 0xffffffff;
  }
  return (h >>> 0).toString(16);
}

// job_id de deduplicacao: hash de titulo+empresa+localidade (normalizado).
function buildJobId(title, company, location) {
  const base = [title || '', company || '', location || ''].join('|').toLowerCase().trim();
  return 'v_' + hashId(base);
}

// Normaliza as respostas do SerpAPI (google_jobs) em vagas limpas + dedup no lote.
// responses = array de objetos json (um por keyword), cada um com jobs_results[].
function normalizeSerpResponses(responses) {
  const out = [];
  const seen = new Set();
  for (const resp of (responses || [])) {
    const jobs = (resp && resp.jobs_results) || [];
    for (const j of jobs) {
      const title = String(j.title || '').trim();
      const company = String(j.company_name || '').trim();
      const location = String(j.location || '').trim();
      if (!title || !company) continue; // guard: vaga sem identificacao minima
      const job_id = buildJobId(title, company, location);
      if (seen.has(job_id)) continue; // dedup dentro da mesma execucao
      seen.add(job_id);
      const via = String(j.via || '').replace(/^via\s+/i, '').trim();
      const description = String(j.description || '').slice(0, 1200);
      let link = '';
      if (Array.isArray(j.apply_options) && j.apply_options.length && j.apply_options[0].link) {
        link = j.apply_options[0].link;
      } else if (j.share_link) {
        link = j.share_link;
      }
      const ext = j.detected_extensions || {};
      out.push({
        job_id, title, company, location, via, description, link,
        schedule_type: ext.schedule_type || '',
        posted_at: ext.posted_at || ''
      });
    }
  }
  return out;
}

// Remove cercas de codigo (```json ... ```), BOM e espacos em volta.
function stripFences(raw) {
  let s = String(raw == null ? '' : raw).replace(/^﻿/, '').trim();
  s = s.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim();
  return s;
}

// Parse DEFENSIVO do JSON do LLM. Nunca lanca: se falhar, marca parse_ok=false
// e match_score=0 (vaga cai no filtro, nao quebra o fluxo - RF/risco da Issue).
function parseLLMOutput(raw) {
  const fail = (motivo, amostra) => ({
    parse_ok: false,
    parse_error: motivo,
    match_score: 0,
    english_requirement: 'desconhecido',
    work_model: 'nao_informado',
    contract_type: 'nao_informado',
    salary_clt: '',
    salary_pj: '',
    salary_confidence: 'estimado',
    cover_letter: '',
    match_reasons: '',
    red_flags: '',
    _raw: String(amostra || '').slice(0, 500)
  });

  const s = stripFences(raw);
  if (!s) return fail('vazio', raw);

  let parsed = null;
  try {
    parsed = JSON.parse(s);
  } catch (e) {
    const m = s.match(/\{[\s\S]*\}/); // tenta extrair o primeiro objeto {...}
    if (m) { try { parsed = JSON.parse(m[0]); } catch (_) { /* ignora */ } }
  }
  if (!parsed || typeof parsed !== 'object') return fail('json_invalido', s);

  const joinArr = (v) => Array.isArray(v) ? v.filter(Boolean).join('; ') : String(v || '');
  const score = Number(parsed.match_score);

  return {
    parse_ok: true,
    parse_error: '',
    match_score: Number.isFinite(score) ? Math.max(0, Math.min(100, Math.round(score))) : 0,
    english_requirement: String(parsed.english_requirement || 'desconhecido').toLowerCase().trim(),
    work_model: String(parsed.work_model || 'nao_informado'),
    contract_type: String(parsed.contract_type || 'nao_informado'),
    salary_clt: String(parsed.salary_clt || ''),
    salary_pj: String(parsed.salary_pj || ''),
    salary_confidence: String(parsed.salary_confidence || 'estimado'),
    cover_letter: String(parsed.cover_letter || ''),
    match_reasons: joinArr(parsed.match_reasons),
    red_flags: joinArr(parsed.red_flags),
    _raw: ''
  };
}

// Regra do no IF: aprova so match >= minimo E ingles na lista permitida.
function isApproved(job, minMatch, allowedEnglish) {
  const score = Number(job.match_score) || 0;
  const eng = String(job.english_requirement || '').toLowerCase().trim();
  return score >= Number(minMatch) && (allowedEnglish || []).includes(eng);
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { hashId, buildJobId, normalizeSerpResponses, stripFences, parseLLMOutput, isApproved };
}


